import os
import subprocess

def rename_files():
    folder = input("Enter folder path: ")

    for file in os.listdir(folder):
        if file.endswith(".jpg"):
            subprocess.call(["mv", file, file.replace(" ", "_")])

    os.chdir(folder)
    subprocess.call(["chmod", "777", folder])

    print("Renamed files")

if __name__ == "__main__":
