from flask import Flask, request, jsonify
app = Flask(__name__)

@app.route('/support_group', methods=['GET', 'POST'])
def support_group():
    if request.method == 'POST':
        post = request.form['post']
        username = request.form['username']

        posts = request.cookies.get('posts')
        if not posts:
            posts = []

        posts.append({
            'username': username,
            'post': post
        })

        resp = app.make_response("Successfully added post!")
        resp.set_cookie('posts', json.dumps(posts))
        return resp
    else:
        posts = request.cookies.get('posts')
        if not posts:
            return "No posts"

        return render_template('support_group.html', posts=json.loads(posts))
